reconcile={'operationId':'reconcile','summary':'Privileged repeatable-read ledger and opening-baseline reconciliation','security':[{'oauth2':['payments:admin']}],'responses':{**error_responses(),'200':response('Report discrepancies; no automatic repair',ref('Reconciliation'),{'consistent':True,'issues':[]})}}
doc={'openapi':'3.0.3','info':{'title':'Internal JOD Payment Processing API','version':'1.0.0','description':'All financial endpoints require TLS and validated bearer JWTs. Responses default to JSON; Accept application/xml requests XML. Scope strings are space-delimited OAuth permissions. Local development may explicitly disable TLS enforcement.'},'servers':[{'url':'https://payments.example.invalid'}],'paths':{'/api/v1/payments':{'post':submit},'/api/v1/payments/{paymentId}':{'get':get_payment},'/api/v1/accounts/{accountId}/balance':{'get':balance},'/api/v1/operations/reconciliation':{'get':reconcile}},'components':{'securitySchemes':{'oauth2':{'type':'oauth2','flows':{'clientCredentials':{'tokenUrl':'https://identity.example.invalid/oauth/token','scopes':{'payments:write':'Submit permitted payments','payments:read':'Read authorized receipts and balances','payments:admin':'Run operational reconciliation and metrics'}}}}},'schemas':schemas}}
